// Qualification framework, loosely inspired by UK CAA terminology (port of src/game/qualifications.ts; table
// generated by Tools/ts2cs.py). These are GAME progression items only: completing them confers no real-world
// aviation privileges.
//   licence       the pilot licence itself (PPL(H), CPL(H))
//   rating        added to a licence (instrument, night)
//   type          aircraft type rating (a twin type also covers multi-engine)
//   authorisation granted by an EMPLOYER/operator (offshore, SAR, winch); not part of the licence
using System.Collections.Generic;
using System.Linq;

namespace Rotorcraft.Game
{
    public enum QualCategory { Licence, Rating, Type, Authorisation }

    public sealed class QualificationDef
    {
        public string id, name, abbrev;
        public QualCategory category;
        public string description;
        public string[] prerequisites = new string[0];   // other qualification ids
        public double requiredHours;                     // simulated flight hours (game-scaled)
        public string[] requiredExercises = new string[0];
        public string[] theoryExams = new string[0];
        public string practicalTest;                     // the exercise id of the practical assessment that awards it
        public string passCriteria;
        public string recurrent;                         // recurrent requirement in plain words
        public string restrictions, unlocks, issuedBy;
        /// <summary>Which development milestone delivers the training content.</summary>
        public int contentMilestone;
        /// <summary>Needs Senior Pilot status (experience, safety record and operator standing).</summary>
        public bool requiresSenior;
    }

